import json, sys
data = json.load(sys.stdin)
registry = json.loads(data['result'])
exps = registry['data']['experiments']
# Find seed42 CRM norm005 spatial - check various naming patterns
candidates = {}
for k, v in exps.items():
    if ('crm' in k.lower() and 'spatial' in k.lower() and ('norm005' in k or 'norm-0.05' in k or 'norm0.05' in k or 'norm005' in k)):
        candidates[k] = {
            'status': v.get('status'),
            'conclusion': v.get('conclusion'),
            'metrics_sr': v.get('metrics', {}).get('success_rate') if v.get('metrics') else None
        }
    # Also check the original seed42 result
    if k in ['eval-3dir-norm005-spatial-s42', 'eval-supp-crm-norm005-spatial-s42']:
        candidates[k] = {
            'status': v.get('status'),
            'conclusion': v.get('conclusion'),
            'metrics': v.get('metrics')
        }
# Also check VLA-only spatial baselines for context
for k, v in exps.items():
    if 'vla-only' in k.lower() and 'spatial' in k.lower() and v.get('conclusion') == 'success':
        sr = v.get('metrics', {}).get('success_rate') if v.get('metrics') else None
        if sr:
            candidates[k] = {'status': v.get('status'), 'conclusion': v.get('conclusion'), 'metrics_sr': sr}
print(json.dumps(candidates, indent=2, ensure_ascii=False))
